  protected async flag(p: Person, reasonText: string, untilText: string): Promise<void> {
    this.personError.set(null);
    this.clearPatronError(p.id);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const reason = reasonText.trim();
    const until = untilText.trim();
    if (!reason || !/^\\d{4}-\\d{2}-\\d{2}$/.test(until)) {
      this.personError.set({ id: p.id, message: 'Enter a reason and an until date.' });
      return;
    }
    try {
      const saved = await firstValueFrom(
        this.http.post<Person>(`${this.url(sheet)}/${p.id}/flag`, { reason, until }, { headers: this.headers() }),
      );
      if (this.session.sheetId() !== sheet) return;
      this.people.update((list) => list.map((x) => (x.id === saved.id ? saved : x)));
    } catch {
      if (this.session.sheetId() === sheet) this.personError.set({ id: p.id, message: 'Only a steward can flag ' + p.name + '.' });
    }
